import math

def _get_joints(agent_components):
    if isinstance(agent_components, dict):
        return agent_components.get("joints", [])
    return []

def build_agent(sandbox):
    # Torso with low mass and optimal dimensions
    torso = sandbox.add_beam(x=10.0, y=2.5, width=2.0, height=0.5, density=1.0)
    sandbox.set_material_properties(torso, restitution=0.1, friction=0.008)  # Max allowed friction

    # Wheels with optimal size and density for low-friction environment
    wheel_radius = 0.3
    wheel_density = 0.45  # Reduced density to meet mass limit

    # Left wheel
    wheel1 = sandbox.add_wheel(x=10.0 - 1.0, y=1.0, radius=wheel_radius, density=wheel_density)
    joint_left = sandbox.add_joint(torso, wheel1, (10.0 - 1.0, 1.0), type='pivot')

    # Right wheel
    wheel2 = sandbox.add_wheel(x=10.0 + 1.0, y=1.0, radius=wheel_radius, density=wheel_density)
    joint_right = sandbox.add_joint(torso, wheel2, (10.0 + 1.0, 1.0), type='pivot')

    return {"body": torso, "joints": [joint_left, joint_right]}

def agent_action(sandbox, agent_body, step_count):
    joints = _get_joints(agent_body)
    if joints:
        # Optimal motor settings for low-friction environment
        for j in joints:
            sandbox.set_motor(j, 25.0, max_torque=50.0)  # Moderate speed and torque

